import json
from urban_micro import intervention_sig

def report(gains):
    cases = ",".join(
        '{{"key":{},"cost":1.000000,"gain":{:.6f},"support":1.000000}}'.format(json.dumps(k), g)
        for k, g in sorted(gains.items()))
    worst = min(gains, key=lambda k: (gains[k], k))
    return ('{"alpha":0.050000,"intervals":[{"start":0.000000,"end":1.000000,"threshold":null,'
            '"pick":["a"],"n":1,"stability":1.000000,"worst":{},"cases":[{}]}]}}\n').format(json.dumps(worst), cases)

# strong positive green gains -> reject true for green, false elsewhere
reports = {
    ("r1","w1"): report({"c1":10.0,"c2":0.1,"c3":-0.1}),
    ("r1","w2"): report({"c1":11.0,"c2":-0.1,"c3":0.1}),
    ("r2","w1"): report({"c1":12.0,"c2":0.2,"c3":0.0}),
}
weights = {("r1","w1"):1, ("r1","w2"):1, ("r2","w1"):1}
kinds = {"c1":"green","c2":"roof","c3":"material"}
data = json.loads(intervention_sig(reports, weights, kinds))
for g in data["intervals"][0]["groups"]:
    items = g["items"]
    # reject-true items must come before reject-false
    rejects = [i["reject"] for i in items]
    assert rejects == sorted(rejects, reverse=True), (g["by"], g["key"], rejects)
    if any(rejects):
        assert items[0]["kind"] == "green" and items[0]["reject"]
print("reject-rank OK")

# empty sample: kind material has no case in region r2 panels? kinds are global per case,
# so make a kind absent entirely from some group: use 4 cases, region r2 panel only has green cases? 
# cases must be common to all intervals/panels, so every panel has all cases -> a group always has
# member cases for a kind only if that kind exists among cases. Make kinds without 'material':
kinds2 = {"c1":"green","c2":"roof","c3":"green"}
data2 = json.loads(intervention_sig(reports, weights, kinds2))
for g in data2["intervals"][0]["groups"]:
    m = next(i for i in g["items"] if i["kind"]=="material")
    assert m["n"] == 0 and m["mean"] == 0.0 and m["se"] == 0.0 and m["p"] == 1.0
    assert m["lower"] == 0.0 and m["upper"] == 0.0
print("empty-sample OK")

# n > 16 -> ValueError
many = {("r","w%d" % i): report({"c1": float(i)}) for i in range(17)}
w_many = {k: 1 for k in many}
try:
    intervention_sig(many, w_many, {"c1":"green"})
    raise AssertionError("no raise")
except ValueError as e:
    assert "16" in str(e)
print("n>16 OK")

# non-dict reports/weights -> TypeError
for args in [("x", {}, {}), ({}, "x", {})]:
    try:
        intervention_sig(*args)
        raise AssertionError("no raise")
    except TypeError:
        pass
print("type errors OK")
